    "officialRecord": "I. İnönü Muharebesi; Albay İsmet Bey komutasındaki Türk Ordusu, Yunan Ordusu ile İnönü'de karşı karşıya geldi. Yunan Ordusu yenildi. Zaferin ardından, Albay İsmet Bey, 1 Mart 1921'de generalliğe terfi ettirildi; TBMM Hükûmetinin uluslararası itibarı da hızla yükseldi.",
    "yasaStory": "1921년 1월 10일 터키·오스만 역사 기록입니다.\n\nI. 이뇌누 전투; İsmet Bey 대령이 지휘하는 터키군은 İnönü에서 그리스군과 맞섰습니다. 그리스군은 패배했습니다. 승리 후, 이스메트 베이(Ismet Bey) 대령은 1921년 3월 1일 장군으로 승진했습니다. 터키 대국민의회 정부의 국제적 명성도 빠르게 높아졌습니다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
