    "yasaStory": "1926년 1월 10일 터키·오스만 역사 기록입니다.\n\nHeyet-i Fesadiye 사건은 종결되었습니다. 실제로 세 가지 경우가 있었습니다. İsmail Hakkı Bey, Circassian Ethem 기동군 볼셰비키 대대 사령관; 이혼한 아내를 살해한 미랄레이 오스만; Kırşehir 부관 Rıza Bey는 쿠르드족 반란과 함께 앙카라에서 반란을 일으켰다는 이유로 사형을 선고 받았습니다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
