    "yasaStory": "1980년 2월 2일 터키·오스만 역사 기록입니다.\n\n1980년 9월 12일 투르키예 쿠데타로 이어지는 과정(1979년 - 1980년 9월 12일): 앙카라의 무장 단체에 개입한 군인 중 한 명인 보병 이병 Zekeriya Önge가 좌익 무장세력 Erdal Eren에 의해 총에 맞아 사망했습니다. 판자 사이에 숨어 있던 에렌은 총을 들고 잡혔습니다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
