    "yasaStory": "1925년 2월 13일 터키·오스만 역사 기록입니다.\n\n셰이크 사이트 반란(Sheikh Sait Rebellion): 모술 문제로 영국과 문제가 있었고 그 해결책은 로잔 회의에서 터키와 영국에 맡겨졌던 시절, 빙골의 겐치(Genç) 지역에서 셰이크 사이트(Sheikh Sait)의 지도 하에 분리주의 운동이 시작되었습니다. 봉기는 Diyarbakır에도 퍼졌습니다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
