    "yasaStory": "1980년 3월 31일 터키·오스만 역사 기록입니다.\n\n1980년 9월 12일 투르키예 쿠데타로 이어지는 과정(1979년 - 1980년 9월 12일): 참모총장 케난 에브렌(Kenan Evren) 장군은 국방장관 아흐메트 이흐산 비린초울루(Ahmet İhsan Birincioğlu)에게 새 대통령이 가능한 한 빨리 선출되어야 한다고 말했습니다. 밴 교도소에서는 58명이 추가로 탈출했습니다. 이스탄불에서 폭탄 현수막을 철거하려던 경찰관 2명이 산산조각이 났습니다. 10개 도시에서 총 11명이 사망했다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
