    "yasaStory": "1926년 3월 13일 터키·오스만 역사 기록입니다.\n\nMustafa Kemal Pasha가 Falih Rıfkı Atay와 Mahmut (Soydan) 신사에게 말한 인생 이야기와 추억의 축약 버전이 Milliyet 신문에 게재되었습니다 (현재의 Milliyet와 동일하지 않습니다. 이 신문은 1935년부터 Tan이라는 이름으로 출판되었습니다).\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
