    "yasaStory": "1982년 3월 13일 터키·오스만 역사 기록입니다.\n\n9월 12일 쿠데타의 11차, 12차, 13차 처형: 불법 TKEP(터키 공산 노동당)를 설립하고 조직의 이름을 알리기 위해 1980년 계약자 Nuri Yapıcı와 MHP 이즈미르 지방 비서 약사 Turan İbrahim을 살해한 좌파 무장세력 Seyit Konuk, İbrahim Ethem Coşkun 및 Necati Vardar 알려진 바에 따르면 처형됐다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
