    "officialRecord": "Halifeliğin kaldırılması ve Osmanlı Hanedanı mensuplarının Türkiye dışına çıkarılmasına ilişkin yasa kabul edildi. Tevhîd-i Tedrîsât Kanunu çıkarıldı. Şer'iye ve Evkaf ve Harbiye Bakanlıkları kaldırıldı. Diyanet İşleri Başkanlığı ve Vakıflar Genel Müdürlüğü kuruldu. Genelkurmay Başkanlığı oluşturuldu ve Hükûmet'ten ayrıldı.",
    "yasaStory": "1924년 3월 3일 터키·오스만 역사 기록입니다.\n\n칼리프 제도 폐지와 투르키예에서 오스만 왕조 구성원의 추방에 관한 법률이 승인되었습니다. Tevhîd-i Tedrîsât 법이 제정되었습니다. 샤리아, 재단, 전쟁 부처가 폐지되었습니다. 종교사무국장단과 재단총국이 설립되었다. 참모진이 창설되어 정부로부터 분리되었습니다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
