    "yasaStory": "1918년 3월 2일 터키·오스만 역사 기록입니다.\n\n군인 가족을 돕는 여성 협회는 Nuriye İsmail(Canbulat) 여사의 의장으로 설립되었습니다. 사회는 Enver Pasha의 아내 Naciye Sultan의 보호를 받았습니다. 이 사회는 1년 동안 6,247명에게 식량을 배급했습니다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
