    "yasaStory": "1923년 3월 1일 터키·오스만 역사 기록입니다.\n\n무스타파 케말 파샤(Mustafa Kemal Pasha)는 터키 대국회의 새로운 업무 기간을 열었습니다. 의회 청중 발코니에서 무스타파 케말의 개회 연설을 지켜본 라티페 하임(Latife Hanım)은 의회에 온 최초의 여성이 되었습니다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
