    "officialRecord": "Bulgar Çarı Kaloyan komutasındaki Bulgarlar ile Latin İmparatoru I. Baudouin komutasındaki Haçlılar arasında Hadrianapolis Muharebesi yaşandı. Savaş, Kumanlar ve Bizanslı Yunanların desteği ile başarılı bir pusu kuran Bulgarlar tarafından kazanıldı.",
    "yasaStory": "1205년 4월 14일 터키·오스만 역사 기록입니다.\n\n아드리아노플 전투는 불가리아 차르 칼로얀이 지휘하는 불가리아군과 라틴 황제 보두앵 1세가 지휘하는 십자군 사이에 벌어졌습니다. 이 전투는 쿠만인과 비잔틴 그리스인의 지원을 받아 성공적인 매복 공격을 감행한 불가리아인에 의해 승리했습니다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
