    "yasaStory": "1941년 6월 23일 터키·오스만 역사 기록입니다.\n\n레파 참사: 영국에 명령된 잠수함과 항공기 함대를 받기 위해 인원을 수송하던 화물선 \"레파\"가 메르신에서 알렉산드리아로 향하던 중 메르신 해안 앞바다에서 잠수함에 의해 침몰했습니다. 168명이 사망하고 32명이 생존한 사건 이후 터키 대국회에서 조사가 시작됐다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
