    "yasaStory": "1961년 7월 22일 터키·오스만 역사 기록입니다.\n\n바르자니 부족의 압력을 견딜 수 없었던 800명의 투르크인들은 이라크 국경을 넘어 투르키예로 망명했습니다. 도착한 사람들은 하카리(Hakkari)의 베네클리(Benekli) 고원에 배치되었고 음식은 비행기로 그들에게 떨어졌습니다. 마이그레이션은 다음 날에도 계속되었습니다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
