    "yasaStory": "1855년 8월 29일 터키·오스만 역사 기록입니다.\n\n최초의 전신 호출은 오스만 제국에서 이루어졌습니다. 이스탄불-에디르네, 이스탄불-슘누 노선이 완성되면서 슈멘에서 이스탄불로 첫 번째 전보가 전송되었습니다. 크림전쟁을 알리는 전보에는 \"연합군이 세바스토폴에 입성했다\"고 적혀 있다. 그것은 쓰여졌다. 터키군도 동맹국에 포함됐다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
