    "yasaStory": "1856년 9월 23일 터키·오스만 역사 기록입니다.\n\nIzmir-Aydın 노선 철도 사업권이 영국 회사에 주어졌습니다. 1866년에 개통된 612km 철도 노선의 허가권은 1950년 10월 15일에 만료될 예정이었습니다. 그러나 신생 공화국 정부는 1935년 5월 30일에 이 노선을 구입했습니다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
