    "officialRecord": "Britanya İmparatorluğu, Alman İmparatorluğu, Avusturya-Macaristan İmparatorluğu, İspanyol İmparatorluğu, Fransa, İtalya, Hollanda, Rus İmparatorluğu ve Osmanlı İmparatorluğu arasında, İstanbul Antlaşması'nın (Convention of Constantinople) nihai metni imzalandı. Buna göre, ilgili devletlerin gemileri hem savaş hem de barış zamanında Süveyş Kanalından geçebilecekler.",
    "yasaStory": "1888년 10월 29일 터키·오스만 역사 기록입니다.\n\n콘스탄티노플 협약의 최종 문서는 대영 제국, 독일 제국, 오스트리아-헝가리 제국, 스페인 제국, 프랑스, ​​이탈리아, 네덜란드, 러시아 제국 및 오스만 제국 간에 체결되었습니다. 이에 따라 관련 국가의 선박은 전시와 평시 모두 수에즈 운하를 통과할 수 있게 된다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
