    "sillokUrl": "https://tr.wikipedia.org/wiki/9_Kas%C4%B1m",
    "officialRecord": "Cumhurbaşkanı Kenan Evren'in Necmettin Erbakan'a tepkisi: ''\"Yarın aynı zamanda Atatürk'ün ölümünün yıl dönümü. Erbakan böyle bir günde Ankara'da bulunur mu? Onun başkenti Konya. Elbette oraya gidecek.\"''",
    "yasaStory": "1985년 11월 9일 터키·오스만 역사 기록입니다.\n\nNecmettin Erbakan에 대한 케난 에브렌(Kenan Evren) 대통령의 반응: ''내일은 아타튀르크 사망 기념일이기도 합니다. 그런 날 Erbakan이 앙카라에 있을까요? 그의 수도는 코냐(Konya)이다. 물론 그는 거기로 갈 것이다.''\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
