    "yasaStory": "1444년 11월 10일 터키·오스만 역사 기록입니다.\n\n바르나 전투: 울라슬로 1세와 2세가 지휘하는 십자군. 오늘날의 불가리아 바르나 시 근처에서 무라트가 이끄는 오스만군 간의 전쟁은 오스만제국의 승리로 이어졌다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
