    "yasaStory": "1595년 11월 19일 터키·오스만 역사 기록입니다.\n\n코카 시난 파샤는 왈라키아 탐험에 실패하여 해고되었습니다. Tekeli Lala Mehmed Pasha가 그의 자리를 대신하여 Grand Vizier가 되었습니다. 그러나 1595년 11월 29일 테켈리 랄라 메흐메드 파샤(Tekeli Lala Mehmed Pasha)가 사망하자 그는 1595년 12월 1일에 다섯 번째이자 마지막으로 재임명되었습니다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
