    "yasaStory": "1954년 12월 18일 터키·오스만 역사 기록입니다.\n\n영국군은 키프로스에서 투르키예, 영국, 미국에 반대하는 시위를 벌이는 군중에게 총격을 가했습니다. 2명이 총에 맞았고, 42명이 체포됐다. 시위는 그리스와 통합을 원하는 키프로스 사람들에 의해 조직되었습니다.\n\n(※ 아래 원문 인용에서 터키어 원문을 함께 확인하실 수 있습니다.)"
